// Fractional-factorial arm design (property P-design).
//
// 2^k ≤ maxArms → the full 2^k factorial. Otherwise a fraction whose last
// factors are generated by signed products of earlier ones; the sign puts the
// all-low arm (every factor at values[0], i.e. today's setup) into the design
// so the baseline is an arm: a generated factor that is the product of m
// factors gets the sign (−1)^(m+1) (at all-low the product is (−1)^m).
//
// - one generator (2^(k-1)): x_k = (−1)^k ∏_{j<k} x_j. Defining word of length
//   k, so k = 5 gives resolution V: every main effect and two-factor
//   interaction lives in its own ±1 column, all mutually orthogonal.
// - two generators (2^(k-2), when 2^(k-1) is still above maxArms): only k = 6
//   (design v2): E = ABC, F = BCD, defining relation I = ABCE = BCDF = ADEF,
//   resolution IV: main effects are orthogonal to each other and to every
//   two-factor interaction (aliased only with three-factor ones); two-factor
//   interactions are aliased with each other (AB = CE, …).

import { createHash } from "node:crypto";

/** A two-level factor. `values[0]` is the "-" value, `values[1]` the "+". */
export type Factor = { name: string; values: [string, string] };

export type Arm = { id: string; flags: Record<string, string> };

/** 2^(k-2) fractions known to be resolution IV: k → for each generated factor, the indexes of the basic factors it is the product of. */
const TWO_GENERATORS: Record<number, number[][]> = { 6: [[0, 1, 2], [1, 2, 3]] };

/** Per generated factor, the basic factors it multiplies. */
function generators(k: number, maxArms: number): number[][] {
  if (2 ** k <= maxArms) return [];
  if (2 ** (k - 1) > maxArms && TWO_GENERATORS[k]) return TWO_GENERATORS[k];
  return [Array.from({ length: k - 1 }, (_, j) => j)];
}

export function design(factors: Factor[], maxArms: number): Arm[] {
  const k = factors.length;
  if (k === 0) return [];
  const gens = generators(k, maxArms);
  const basic = k - gens.length;
  const arms: Arm[] = [];
  for (let mask = 0; mask < 2 ** basic; mask++) {
    const signs: number[] = [];
    for (let j = 0; j < basic; j++) signs.push(mask & (1 << j) ? 1 : -1);
    for (const g of gens) signs.push(((g.length + 1) % 2 ? -1 : 1) * g.reduce((p, j) => p * signs[j], 1));
    const flags: Record<string, string> = {};
    for (let j = 0; j < k; j++) flags[factors[j].name] = signs[j] > 0 ? factors[j].values[1] : factors[j].values[0];
    // id: one sign per factor, "+" = high value. Unique because each arm is a
    // distinct mask over the basic factors.
    arms.push({ id: signs.map((s) => (s > 0 ? "+" : "-")).join(""), flags });
  }
  return arms;
}

// One design per stratum (redesign §7.2), named by a content id instead of v1…v4; the design() above stays the
// runtime's until the engine moves to strata. This file imports only node builtins: bench ships it alone.

/** A factor level: what the add-on sets on its lever (a range lever's level is a fraction q of the matched range, §7.4). */
export type Level = string | number | boolean;
/** A lever id, `<target>.<name>` (§7.1), e.g. "cache-lifecycle.mainCacheTtl". */
export type LeverId = string;
/** A two-level factor of a stratum: `levels[0]` is the low ("0") level, `levels[1]` the high ("1") one. */
export type FactorSpec = { name: string; lever: LeverId; levels: readonly [Level, Level] };

/** JSON with the keys of every object sorted and no whitespace; arrays keep their order. */
export function canonical(x: unknown): string {
  if (Array.isArray(x)) return `[${x.map((v) => canonical(v ?? null)).join(",")}]`;
  if (x !== null && typeof x === "object") {
    const o = x as Record<string, unknown>;
    const keys = Object.keys(o).filter((k) => o[k] !== undefined).sort();
    return `{${keys.map((k) => `${JSON.stringify(k)}:${canonical(o[k])}`).join(",")}}`;
  }
  return JSON.stringify(x);
}

/** The design id: the first 12 hex of sha256 over the canonical JSON of the levers, their levels and the generators (factor names are labels). */
export function designId(factors: readonly FactorSpec[], generators: readonly string[]): string {
  const content = { factors: factors.map(({ lever, levels }) => ({ lever, levels })), generators };
  return createHash("sha256").update(canonical(content)).digest("hex").slice(0, 12);
}

/** An arm of a design: `name` = one bit per factor in factor order ("1" = levels[1]), e.g. "010"; `levels` by factor name. */
export type DesignArm = { name: string; levels: Record<string, Level> };
export type Design = { id: string; stratum: string; factors: FactorSpec[]; generators: string[]; arms: DesignArm[] };

/** Generated columns per factor count: resolution IV (k = 4, 6) and V (k = 5); letters are factor positions (A = first). */
export const GENERATORS: Readonly<Record<4 | 5 | 6, readonly string[]>> = { 4: ["D=ABC"], 5: ["E=ABCD"], 6: ["E=ABC", "F=BCD"] };
const LETTERS = "ABCDEF";

/**
 * The design of a stratum's factors: the full 2^k factorial for k ≤ 3, else the basic factors' full factorial with the
 * generated columns of GENERATORS[k]; k > 6 throws. A generated column is the signed product (−1)^(m+1) of the m
 * factors its word names, so the all-low arm (levels[0] everywhere, today's behaviour) is an arm. Arms in mask order
 * over the basic factors, first factor fastest.
 */
export function designFor(stratum: string, s: { factors: readonly FactorSpec[] }): Design {
  const factors = [...s.factors];
  const k = factors.length;
  if (k > 6) throw new Error(`experiments stratum ${stratum}: ${k} factors, at most 6`);
  const generators = k <= 3 ? [] : [...GENERATORS[k as 4 | 5 | 6]];
  const basic = k - generators.length;
  const words = generators.map((g, i) => {
    const [target, word] = g.split("=");
    const idx = [...word].map((c) => LETTERS.indexOf(c));
    if (target !== LETTERS[basic + i] || idx.some((j) => j < 0 || j >= basic)) throw new Error(`generator ${g}: not over the basic factors of ${k}`);
    return idx;
  });
  const arms: DesignArm[] = [];
  for (let mask = 0; mask < 2 ** basic; mask++) {
    const signs: number[] = Array.from({ length: basic }, (_, j) => (mask & (1 << j) ? 1 : -1));
    for (const w of words) signs.push((w.length % 2 ? 1 : -1) * w.reduce((p, j) => p * signs[j], 1));
    const bits = signs.map((x) => (x > 0 ? 1 : 0));
    arms.push({ name: bits.join(""), levels: Object.fromEntries(factors.map((f, j) => [f.name, f.levels[bits[j]]])) });
  }
  return { id: designId(factors, generators), stratum, factors, generators, arms };
}
